class Solution:

	def deleteMid(self, s, sizeOfStack):
		if sizeOfStack % 2 == 0:
			index = sizeOfStack // 2
		else:
			index = (sizeOfStack + 1) // 2 - 1

		def recursive(s, i):
			if i == index:
				s.pop()
				return
			val = s.pop()
			recursive(s, i + 1)
			s.append(val)
		recursive(s, 0)
		return s

