class Solution:

	def findSequences(self, startWord, targetWord, wordList):
		st = set(wordList)
		queue = deque()
		queue.append([startWord])
		ans = []
		usedonLevel = [startWord]
		level = 0
		while queue:
			vec = queue.popleft()
			if len(vec) > level:
				level += 1
				for ele in usedonLevel:
					st.discard(ele)
			word = vec[-1]
			if word == targetWord:
				if not ans:
					ans.append(vec)
				elif len(ans[0]) == len(vec):
					ans.append(vec)
			for i in range(0, len(word)):
				original = word[i]
				for ch in 'abcdefghijklmnopqrstuvwxyz':
					word = word[:i] + ch + word[i + 1:]
					if word in st:
						vec.append(word)
						queue.append(vec.copy())
						usedonLevel.append(word)
						vec.pop()
					word = word[:i] + original + word[i + 1:]
		return ans

class Solution:

	def numSubmat(self, mat: List[List[int]]) -> int:
		(n, m) = (len(mat), len(mat[0]))
		heights = [0] * m
		res = 0
		for i in range(0, n):
			stack = []
			count = 0
			for j in range(0, m):
				if mat[i][j] == 1:
					heights[j] += 1
				else:
					heights[j] = 0
			for (index, height) in enumerate(heights):
				while stack and height < heights[stack[-1]]:
					curr = stack.pop()
					left = stack[-1] if stack else -1
					count -= (heights[curr] - height) * (curr - left)
				count += height
				res += count
				stack.append(index)
		return res

