	(x1, y1) = p1
	(x2, y2) = p2
	if x1 * y2 == x2 * y1:
		c = 0
		a = 1
		if y1 != 0:
			b = -x1 / y1
		elif y2 != 0:
			b = -x2 / y2
		else:
			a = 0
			b = 1
		return (a, b, c)
