def comm(x1, y1, r1, x2, y2, r2):
	if r1 == r2:
		(a, b, c) = get_line((x1, y1), (x2, y2))
		return (True, b, -a, a * (y1 + y2) / 2 - b * (x1 + x2) / 2)
	else:
		c = r1 ** 2 / r2 ** 2
		x = (c * x2 - x1) / (c - 1)
		y = (c * y2 - y1) / (c - 1)
		r = math.sqrt((c * (x1 - x2) ** 2 + c * (y1 - y2) ** 2) / (c - 1) ** 2)
		return (False, x, y, r)

