import heapq as h

class Solution:

	def maxTripletSum(self, arr, n, K):
		hashmap = {}
		maxheap = []
		for i in range(0, n):
			if arr[i] in hashmap:
				hashmap[arr[i]] = hashmap[arr[i]] + 1
			elif arr[i] not in hashmap:
				hashmap[arr[i]] = 1
		for (key, value) in hashmap.items():
			h.heappush(maxheap, -value)
		while K > 0:
			if maxheap:
				temp = -h.heappop(maxheap)
				temp = temp - 1
				K = K - 1
				if temp > 0:
					h.heappush(maxheap, -temp)
		return len(maxheap)

