def getGrundy(x, y):
	if grundy[x][y] != -1:
		return grundy[x][y]
	s = set()
	for (i, j) in moveCoin(x, y):
		s.add(getGrundy(i, j))
	mex = 0
	while mex in s:
		mex += 1
	grundy[x][y] = mex
	return mex
