class Solution:

	def angleClock(self, hour: int, minutes: int) -> float:
		hour_angle = hour * 30 + minutes / 12 * 6
		if hour_angle > 360:
			hour_angle -= 360
		min_angle = minutes / 5 * 30
		if min_angle > 360:
			min_angle -= 360
		diff = abs(hour_angle - min_angle)
		return diff if diff <= 360 - diff else 360 - diff

import heapq
from collections import defaultdict

class Solution:
    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
        dist = [[0 if cell == 0 else float('inf') for cell in row] for row in mat]
        heap = []
        deleted = defaultdict(int)
        m = len(mat)
        n = len(mat[0])
        for i in range(m):
            for j in range(n):
                heapq.heappush(heap, (dist[i][j], i, j))
        while len(heap) > 0:
            currdist, i, j = heapq.heappop(heap)
            while (currdist, i, j) in deleted and len(heap) > 0:
                deleted[(currdist, i, j)] -= 1
                if deleted[(currdist, i, j)] == 0:
                    del deleted[(currdist, i, j)]
                currdist, i, j = heapq.heappop(heap)
            adj = []
            if i > 0:
                adj.append((i - 1, j))
            if i < m - 1:
                adj.append((i + 1, j))
            if j > 0:
                adj.append((i, j - 1))
            if j < n - 1:
                adj.append((i, j + 1))
            for a, b in adj:
                if dist[a][b] > 1 + currdist:
                    deleted[(dist[a][b], a, b)] += 1
                    dist[a][b] = 1 + currdist
                    heapq.heappush(heap, (1 + currdist, a, b))
        return dist

class Solution:

	def DifferOne(self, a, b):
		x = max(a, b)
		y = min(a, b)
		c = bin(x)
		d = bin(y)
		if c == d:
			return 0
		else:
			m = str(c)[2:].zfill(30)
			n = str(d)[2:].zfill(30)
			s = 0
			for i in range(len(m)):
				if m[i] != n[i]:
					s += 1
				else:
					s += 0
			if s == 1:
				return 1
			else:
				return 0

