class Solution:

	def sameFreq(self, s):
		temp = {}
		for i in s:
			if i in temp:
				temp[i] += 1
			else:
				temp[i] = 1
		freq = temp[s[0]]
		flag = False
		for i in temp:
			if freq == temp[i]:
				continue
			elif not flag and (freq + 1 == temp[i] or temp[i] == 1):
				flag = True
			elif freq == temp[i] + 1:
				freq -= 1
			else:
				return 0
		return 1

def survivor(x):
	if x == 1:
		return 0
	if x % 2 == 0:
		return 2*survivor(x // 2)
	else:
		s = x // 2 + 1
		a = (survivor(s) - 1) % s
		return 2*a

