def printKDistantfromLeaf(root, k):
	lis = []
	se = set()

	def fun(root):
		if root == None:
			return
		lis.append(root)
		if root.left == None and root.right == None:
			dis = len(lis) - k - 1
			if dis >= 0:
				se.add(lis[dis])
			lis.pop()
			return
		fun(root.left)
		fun(root.right)
		lis.pop()
	fun(root)
	return len(se)

from collections import deque

def tree_by_levels(node):
	if not node:
		return []
	(res, queue) = ([], deque([node]))
	while queue:
		n = queue.popleft()
		res.append(n.value)
		if n.left is not None:
			queue.append(n.left)
		if n.right is not None:
			queue.append(n.right)
	return res

