	def hasPathSum(self, root, S):

		def path(rt, c, s):
			if rt is None:
				return
			if rt.left is None and rt.right is None:
				return s == c + rt.data
			return path(rt.left, c + rt.data, s) or path(rt.right, c + rt.data, s)
		return path(root, 0, S)

