class Solution:
    def findMaxConsecutiveOnes(self, nums: List[int]) -> int:
        nums.append(-1)
        maxOnes = 0
        curr = 0
        for num in nums:
            if num <= 0:
                maxOnes = max(maxOnes, curr)
                curr = 0
            else:
                curr += 1
        return maxOnes

def next_day_of_week(current_day, available_week_days):
	x = 2 ** current_day
	while not x & available_week_days:
		x = max(1, x * 2 % 2 ** 7)
	return x.bit_length()

