def sumOfLastN_Nodes(head, n):
	if n == 0 or head is None:
		return 0
	slow = head
	fast = head
	for _ in range(n):
		if fast is None:
			return 0
		fast = fast.next
	while fast:
		slow = slow.next
		fast = fast.next
	node_sum = 0
	while slow:
		node_sum += slow.data
		slow = slow.next
	return node_sum

