class Solution:

	def zigZag(self, arr, n):
		for i in range(1, n):
			a = arr[i]
			b = arr[i - 1]
			if i % 2 == 1 and b > a:
				t = a
				arr[i] = b
				arr[i - 1] = t
			elif i % 2 == 0 and b < a:
				t = a
				arr[i] = b
				arr[i - 1] = t
		return arr

