class Solution:

	def arrayRepresentHeap(self, arr, n):
		if not arr:
			return 1
		seen = False
		for i in range(n):
			left = i * 2 + 1
			right = left + 1
			if left <= n - 1:
				if seen or arr[left] > arr[i]:
					return 0
			else:
				seen = True
			if right <= n - 1:
				if seen or arr[right] > arr[i]:
					return 0
			else:
				seen = True
		return 1

