class Solution:

	def minChar(self, str):
		ha = [0] * len(s)
		(i, j) = (0, len(s) - 1)
		ans = 0
		while i < j:
			if s[i] == s[j]:
				if i == 0:
					ha[i] = 1
				else:
					ha[i] = 1 + ha[i - 1]
				i += 1
				j -= 1
			elif i == 0:
				ans = len(s) - j
				j -= 1
			else:
				i = ha[i - 1] // 2
				ans = len(s) - (j + 1) - i
		return ans

