def scc(g):
	n = g.n
	cur = g.head
	last = [None] * n
	order = [-1] * n
	low = [-1] * n
	bl = [-1] * n
	idx = []
	st = []
	num = 0
	for i in range(n):
		if order[i] != -1:
			continue
		rec = [i]
		while rec:
			v = rec[-1]
			if last[v] is None:
				order[v] = low[v] = num
				num += 1
				st.append(v)
			else:
				low[v] = min(low[v], low[last[v].to])
			found = False
			while cur[v] is not None:
				e = cur[v]
				cur[v] = e.nx
				to = e.to
				if order[to] == -1:
					rec.append(to)
					last[v] = e
					found = True
					break
				elif bl[to] == -1:
					low[v] = min(low[v], order[to])
			if not found:
				rec.pop()
				if order[v] == low[v]:
					c = len(idx)
					tmp = []
					while True:
						a = st.pop()
						bl[a] = c
						tmp.append(a)
						if v == a:
							break
					idx.append(tmp)
	s = len(idx)
	for i in range(n):
		bl[i] = s - 1 - bl[i]
	idx.reverse()
	return (s, bl, idx)

