class Solution:

	def util(self, a, i, j, n, m, k):
		global dp
		if i >= n or j >= m or k < 0:
			return 0
		if i == n - 1 and j == m - 1:
			if k - a[i][j] == 0:
				return 1
			return 0
		if dp[i][j][k] != -1:
			return dp[i][j][k]
		dp[i][j][k] = self.util(a, i + 1, j, n, m, k - a[i][j]) + self.util(a, i, j + 1, n, m, k - a[i][j])
		return dp[i][j][k]

	def numberOfPath(self, N, K, arr):
		global dp
		dp = [[[-1 for x in range(K + 1)] for i in range(N)] for j in range(N)]
		return self.util(arr, 0, 0, N, N, K)

class Solution:

	def countWays(self, n, k):
		dp = []
		for i in range(n):
			dp.append([0, 0])
		dp[0] = [k, 0]
		for i in range(1, n):
			dp[i][0] = (dp[i - 1][0] * (k - 1) + dp[i - 1][1] * (k - 1)) % (10 ** 9 + 7)
			dp[i][1] = dp[i - 1][0]
		return sum(dp[n - 1]) % (10 ** 9 + 7)

