		r3 = ellipse_range(x1, y2, e)
		r4 = ellipse_range(x2, y2, e)
		if not (r1 < limit or r2 < limit or r3 < limit or (r4 < limit)):
			return None
		if not (r1 < 0 and r2 < 0 and (r3 < 0) and (r4 < 0)):
			ellipses2.append(e)
	mx = (x1 + x2) / 2
	my = (y1 + y2) / 2
	ans = solve(edges2, ellipses2, x1, y1, mx, my)
