class Solution:

	def BoundaryTraversal(self, matrix, n, m):
		ls = []
		if n == 1:
			return matrix[0]
		if m == 1:
			for i in range(n):
				ls.append(matrix[i][0])
			return ls
		for j in range(m - 1):
			ls.append(matrix[0][j])
		for i in range(n):
			ls.append(matrix[i][m - 1])
		for j in range(m - 2, -1, -1):
			ls.append(matrix[n - 1][j])
		for i in range(n - 2, 0, -1):
			ls.append(matrix[i][0])
		return ls

