    def validUtf8(self, data: List[int]) -> bool:
        n = len(data)
        i = 0
        while i < n:
            ctr = self.getctr(data[i])
            if ctr > 4 or ctr == 1:
                return False
            if i + ctr > n:
                return False
            j = i + ctr
            i += 1
            while i < j:
                if self.getctr(data[i]) != 1:
                    return False
                i += 1
        return True

class Solution:
    def sumOfDistancesInTree(self, n, edges):
        res = [0] * n
        subctr = [0] * n
        graph = [[] for _ in range(n)]
        for a, b in edges:
            graph[a].append(b)
            graph[b].append(a)
        def dfs(root, prev):
            s = 0
            ctr = 1
            for j in graph[root]:
                if j != prev:
                    currs, currctr = dfs(j, root)
                    ctr += currctr
                    s += currs + currctr
            subctr[root] = ctr
            return s, ctr
        res[0], tmp = dfs(0, -1)
        stack = [(0, -1)]
        while len(stack) > 0:
            curr, prev = stack.pop()
            for j in graph[curr]:
                if j != prev:
                    res[j] = n + res[curr] - 2 * subctr[j]
                    stack.append((j, curr))
        return res

from collections import Counter

def get_key_length(cipher_text, max_key_length):
	avg_IC_by_keylen = {}
	for key_len in range(1, max_key_length + 1):
		ICs = []
		for i in range(key_len):
			sub_str = cipher_text[i::key_len]
			freq = Counter(sub_str)
			IC = sum((v * (v - 1) for (k, v) in freq.items())) / (len(sub_str) * (len(sub_str) - 1))
			ICs.append(IC)
		avg_IC_by_keylen[key_len] = sum(ICs) / key_len
	return max(avg_IC_by_keylen, key=avg_IC_by_keylen.get)

