def resolve(x, k):
	if k == 0:
		return x
	ret = []
	min_value_idx = get_sample_idx_first(x, k)
	ret.append(x[min_value_idx])
	k = k - min_value_idx
	for i in range(min_value_idx + 1, len(x)):
		while len(ret) > 1 and k and (ret[-1] > x[i]):
			ret.pop()
			k -= 1
		ret.append(x[i])
	while len(ret) > 1 and k:
		ret.pop()
		k -= 1
	return ''.join(ret)

