def cross(c1, c2):
	return c1.real * c2.imag - c1.imag * c2.real

def dot(c1, c2):
	return c1.real * c2.real + c1.imag * c2.imag

def ccw(p0, p1, p2):
	a = p1 - p0
	b = p2 - p0
	cross_ab = cross(a, b)
	if cross_ab > 0:
		return 1
	elif cross_ab < 0:
		return -1
	elif dot(a, b) < 0:
		return 1
	elif abs(a) < abs(b):
		return -1
	else:
		return 0

def intersect(p1, p2, p3, p4):
	if ccw(p1, p2, p3) * ccw(p1, p2, p4) <= 0 and ccw(p3, p4, p1) * ccw(p3, p4, p2) <= 0:
		return True
	else:
		return False

def get_distance_sp(sp1, sp2, p):
	a = sp2 - sp1
	b = p - sp1
	if dot(a, b) < 0:
		return abs(b)
	c = sp1 - sp2
	d = p - sp2
	if dot(c, d) < 0:
		return abs(d)
	return abs(cross(a, b) / a)

