class Solution:

	def reverseVowels(self, s):
		vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
		char_list = list(s)
		(first, last) = (0, len(char_list) - 1)
		while first < last:
			while first < last and char_list[first] not in vowels:
				first += 1
			while first < last and char_list[last] not in vowels:
				last -= 1
			if first >= last:
				break
			(char_list[first], char_list[last]) = (char_list[last], char_list[first])
			first += 1
			last -= 1
		return ''.join(char_list)

class Solution:

	def solve(self, k, n, d):
		if k == n - 1:
			num = 0
			for i in d:
				num = num * 10 + i
			if num % 17 == 0 and num > self.ans:
				self.ans = num
			return
		self.solve(k + 1, n, d)
		for i in range(k + 1, n):
			if d[i] != d[i - 1]:
				(d[i], d[k]) = (d[k], d[i])
				self.solve(k + 1, n, d)
				(d[i], d[k]) = (d[k], d[i])

