class Solution:

	def longestIncreasingSubsequence(self, N, arr):
		(res, dp, path) = ([], [1] * N, [i for i in range(N)])
		lisInd = lis = 0
		for i in range(N):
			for prev in range(i):
				if arr[prev] < arr[i] and dp[prev] + 1 > dp[i]:
					dp[i] = dp[prev] + 1
					path[i] = prev
					if dp[i] > lis:
						lis = dp[i]
						lisInd = i
		while path[lisInd] != lisInd:
			res.append(arr[lisInd])
			lisInd = path[lisInd]
		res.append(arr[lisInd])
		return res[::-1]

