def generalizedEuclidianAlgorithm(a, b):
	if b > a:
		return generalizedEuclidianAlgorithm(b, a)
	elif b == 0:
		return (1, 0)
	else:
		(x, y) = generalizedEuclidianAlgorithm(b, a % b)
		return (y, x - a // b * y)

def inversemodp(a, p):
	a = a % p
