					A1,B1 = B[x+i-1]
					A0,B0 = dp(x+i,max(A1,a),max(B1,b))
					A2,B2 = max(A0,A1,a),max(B0,B1,b)
					diff = 0
					if A2>a: diff += A2-a
					if B2>b: diff += B2-b
					if diff < ans:
						ans = diff
						mem = A2,B2
			cache[(x,a,b)] = mem
	return cache[(x,a,b)]

