class Solution:

	def optimalSearchTree(self, keys, freq, n):
		dp = [[0 for i in range(n)] for j in range(n)]
		for g in range(n):
			for (i, j) in zip(range(n - g), range(g, n)):
				if g == 0:
					dp[i][j] = freq[i]
				if g == 1:
					dp[i][j] = min(2 * freq[i] + freq[j], 2 * freq[j] + freq[i])
				else:
					mini = 99999999999999
					sumi = 0
					for x in range(i, j + 1):
						sumi += freq[x]
					for k in range(i, j + 1):
						left = 0 if k == i else dp[i][k - 1]
						right = 0 if k == j else dp[k + 1][j]
						if left + right + sumi < mini:
							mini = left + right + sumi
					dp[i][j] = mini
		return dp[0][n - 1]

def isAnagramSubstring(string, substring):
    if len(substring) > len(string):
        return False

    chars = {}

    for char in string[:len(substring)]:
        if char in chars:
            chars[char] += 1
        else:
            chars[char] = 1

    for char in substring:
        if char not in chars or chars[char] == 0:
            return False
        else:
            chars[char] -= 1

    return True

