from collections import deque

def find_shortest_cycle(G, s):
	dq = deque()
	N = len(G)
	INF = float('inf')
	dist = [INF] * N
	dist[s] = 0
	parent = [-1] * N
	ans_last = None
	dq.append(s)
	while dq and ans_last is None:
		v = dq.popleft()
		d = dist[v]
		for n in G[v]:
			if dist[n] == 0:
				ans_last = v
				parent[n] = v
				break
			elif dist[n] == INF:
				dist[n] = d + 1
				parent[n] = v
				dq.append(n)
	if ans_last:
		g = ans_last
		route = [g]
		while g != s:
			g = parent[g]
			route.append(g)
		return list(reversed(route))
	return None

