class Solution:

	def sentences(self, list: List[List[str]]) -> List[List[str]]:
		ans = []

		def backtrack(i, curr):
			if i >= len(list):
				ans.append([curr.lstrip()])
				return
			for j in list[i]:
				curr = curr + ' ' + j
				backtrack(i + 1, curr)
				curr = curr[:-(len(j) + 1)]
		backtrack(0, '')
		return ans

