from collections import deque

class Solution:
    def countStudents(self, students: List[int], sandwiches: List[int]) -> int:
        s = deque(students)
        sw = deque(sandwiches)
        ss = sum(s)
        while s:
            if s[0] == sw[0]:
                ss -= s.popleft()
                sw.popleft()
            else:
                s.append(s.popleft())
                if ss == 0 or ss == len(s):
                    break
        return len(s)

class Solution:

	def partition(self, head, x):
		less = []
		gre = []
		eq = []
		tmp = head
		while tmp:
			if tmp.data < x:
				less.append(tmp.data)
			elif tmp.data == x:
				eq.append(tmp.data)
			elif tmp.data > x:
				gre.append(tmp.data)
			tmp = tmp.next
		less = less + eq + gre
		head = None
		tmp = None
		for i in less:
			if head is None:
				node = Node(i)
				node.next = None
				head = node
				tmp = node
			else:
				node = Node(i)
				tmp.next = node
				tmp = node
		return head

