class Solution:
    def DFS(self, graph, i, v):
        for j in graph[i]:
            self.edges.add((min(i, j), max(i, j)))
            if j not in v:
                v.add(j)
                self.DFS(graph, j, v)

    def makeConnected(self, n: int, connections: List[List[int]]) -> int:
        graph = defaultdict(set)
        for a, b in connections:
            graph[a].add(b)
            graph[b].add(a)
        ctr = 0
        extra = 0
        v = set()
        for i in range(n):
            if i not in v:
                ctr += 1
                currv = {i}
                self.edges = set()
                self.DFS(graph, i, currv)
                extra += len(self.edges) - len(currv) + 1
                v.update(currv)
        if extra < ctr - 1:
            return -1
        return ctr - 1

def InfinitePrefix(n, x, s):
	rec = [0] * n
	for (i, c) in enumerate(s):
		if c == '0':
			rec[i] = rec[i - 1] + 1
		else:
			rec[i] = rec[i - 1] - 1
	loop = rec[-1]
	res = 0
	if x == 0:
		res = 1
	if loop == 0:
		for r in rec:
			if x == r:
				return -1
		return res
	for r in rec:
		if (x - r) % loop == 0 and (x - r) // loop >= 0:
			res += 1
	return res
