def carmichael(x):
	r = 1
	b = 0
	while x & 1 == 0:
		b += 1
		x >>= 1
	if b > 1:
		r = 2 if b == 2 else 2 ** (b - 2)
	y = 3
	while y * y <= x:
		if x % y == 0:
			c = 0
			while x % y == 0:
				x //= y
				c += 1
			r = lcm(r, (y - 1) * y ** (c - 1))
		y += 1
	if x > 1:
		r = lcm(r, x - 1)
	return r

