def bfs(s, graph):
	que = deque([(s, 0, 0)])
	while True:
		(s, pre_cnt, depth) = que.popleft()
		pre_color = s[0]
		colors = ['R', 'G', 'B']
		colors.remove(pre_color)
		for (si, color) in zip((s, s[:]), colors):
			cnt = paintout_graph(si, graph, color)
			if cnt == len(si):
				return depth
			if cnt == pre_cnt:
				break
			que.append((si, cnt, depth + 1))
from collections import deque

def paintout_sq(s, color, w, h, x, y):
	(neighbor, pre_color) = (set(), s[y * w + x])
	que = deque([(x, y)])
	while len(que):
		(x, y) = que.pop()
		pos = y * w + x
		if s[pos] == pre_color:
			s[pos] = color
			if 0 < x:
				que.append((x - 1, y))
			if 0 < y:
				que.append((x, y - 1))
			if x + 1 < w:
				que.append((x + 1, y))
			if y + 1 < h:
				que.append((x, y + 1))
		elif s[pos] != color and isinstance(s[pos], int):
			neighbor.update([s[pos]])
