class Solution:

	def leastInterval(self, N, K, tasks):
		dic = {}
		for i in tasks:
			if i in dic:
				dic[i] += 1
			else:
				dic[i] = 1
		ans = 0
		heap = []
		for i in dic:
			heapq.heappush(heap, [-dic[i], i])
		while heap:
			temp = []
			p = heapq.heappop(heap)
			ans += 1
			p[0] = -p[0]
			p[0] -= 1
			if p[0] > 0:
				p[0] = -p[0]
				temp.append(p)
			if len(heap) >= K:
				for i in range(K):
					p = heapq.heappop(heap)
					ans += 1
					p[0] = -p[0]
					p[0] -= 1
					if p[0] > 0:
						p[0] = -p[0]
						temp.append(p)
			else:
				if len(temp) > 0:
					ans += K - len(heap)
				for i in range(len(heap)):
					p = heapq.heappop(heap)
					ans += 1
					p[0] = -p[0]
					p[0] -= 1
					if p[0] > 0:
						p[0] = -p[0]
						temp.append(p)
			for i in range(len(temp)):
				heapq.heappush(heap, temp[i])
		return ans

