def delete_empty_dirs(path):
    for root, directories, files in os.walk(path):
        for directory in directories:
            joined_path = os.path.join(root, directory)
            try:
                os.rmdir(joined_path)
            except OSError:
                # Directory not empty
                pass

def highest_frequency(string):
    freq_map = {}
    max_freq = 0
    result = ""
    for char in string:
        char = char.upper()
        if char in freq_map:
            freq_map[char] += 1
            if freq_map[char] > max_freq:
                max_freq = freq_map[char]
                result = char
        else:
            freq_map[char] = 1
    return result

