	return ((p2[0] + p1[0]) / 2, (p2[1] + p1[1]) / 2)

def circumradius(p1, p2, p3):
	d1 = dist(p2, p3)
	d2 = dist(p1, p3)
	d3 = dist(p2, p1)
	return d1 * d2 * d3 / sqrt((d1 + d2 + d3) * (d1 + d2 - d3) * (d1 - d2 + d3) * (-d1 + d2 + d3))
