def circumcenter(p1, p2, p3):
	d = 2 * (cross(p1, p2) + cross(p2, p3) + cross(p3, p1))
	if d == 0:
		return None
	l1 = dot(p1, p1)
	l2 = dot(p2, p2)
	l3 = dot(p3, p3)
	return ((l1 * (p2[1] - p3[1]) + l2 * (p3[1] - p1[1]) + l3 * (p1[1] - p2[1])) / d, (l1 * (p3[0] - p2[0]) + l2 * (p1[0] - p3[0]) + l3 * (p2[0] - p1[0])) / d)

def circumcircle(p1, p2, p3):
	center = circumcenter(p1, p2, p3)
	if center is None:
		return None
	radius = circumradius(p1, p2, p3)
	return (radius, center)
