def smallest_circle_trivial(points):
	npoints = len(points)
	if not npoints:
		return (0, (0, 0))
	if npoints == 1:
		return (0, points[0])
	if npoints == 2:
		return circle_diameter(*points)
	if npoints > 3:
		raise ValueError('smallest_circle_trivial: non-trivial', npoints, points)
	(p1, p2, p3) = points
	s1 = vec(p2, p3)
	s2 = vec(p3, p1)
	s3 = vec(p1, p2)
	if dot(s1, s2) >= 0:
		return circle_diameter(p1, p2)
	if dot(s2, s3) >= 0:
		return circle_diameter(p2, p3)
	if dot(s3, s1) >= 0:
		return circle_diameter(p3, p1)
	return circumcircle(p1, p2, p3)
