def run_queries(n, arrs, queries):
	for (query, *parameters) in queries:
		if query == 1:
			arrs[parameters[0]] = reverse(arrs[parameters[0]], *parameters[1:])
			assert len(arrs[parameters[0]]) == n
		elif query == 2:
			arrs[parameters[0]] = swap1(arrs[parameters[0]], *parameters[1:])
			assert len(arrs[parameters[0]]) == n
		elif query == 3:
			arrs = swap2(arrs[0], arrs[1], *parameters)
			assert n == len(arrs[0])
			assert n == len(arrs[1])
		elif query == 4:
			circle = smallest_circle_welzl(zip(arrs[0][parameters[0] - 1:parameters[1]], arrs[1][parameters[0] - 1:parameters[1]]))
			print('{:.2f}'.format(circle[0]))
		else:
			raise ValueError('run_queries', query, parameters)

