def dfsVisit(u, color, reglas, diamMax, d):
	color[u] = _GRIS
	for r in reglas[u]:
		if esUnaMalaRegla(r, d):
			continue
		sumaMax = r.diamantes
		for v in r.monstruos:
			if color[v] == _BLANCO:
				dfsVisit(v, color, reglas, diamMax, d)
				if diamMax[v] > 0:
					sumaMax += diamMax[v]
			elif color[v] == _GRIS:
				diamMax[v] = -2
			elif color[v] == _NEGRO:
				sumaMax += diamMax[v]
			if diamMax[v] == -2:
				diamMax[u] = -2
				color[u] = _NEGRO
				return
		diamMax[u] = max(diamMax[u], sumaMax)
	color[u] = _NEGRO

def dfs(reglas, d):
