def dijkstra(reglas, s, m, perteneceA):
	n = len(reglas)
	d = []
	(Q, visto) = ([], [])
	(k, sumaMin) = ([0] * m, [])
	for u in range(n):
		d.append(_OO)
		visto.append(False)
		for r in reglas[u]:
			sumaMin.append(0)
			k[r.id] = len(r.monstruos)
	d[s] = 0
	Q.append((0, s))
	heapq.heapify(Q)
	while len(Q) != 0:
		u = heapq.heappop(Q)[1]
		if visto[u]:
			continue
		visto[u] = True
		for p in perteneceA[u]:
			r = reglas[p[0]][p[1]]
			ocurrencias = p[2]
			k[r.id] -= ocurrencias
			sumaMin[r.id] += d[u] * ocurrencias
			if k[r.id] == 0 and d[r.deMonstruo] > sumaMin[r.id] + r.diamantes:
				d[r.deMonstruo] = sumaMin[r.id] + r.diamantes
				heapq.heappush(Q, (d[r.deMonstruo], r.deMonstruo))
	return d

