class SegmentTree:

	def __init__(self, arr, combinerFunction, isCommutative=True):
		self.n = len(arr)

		def cmb(a, b):
			if a == None:
				return b
			if b == None:
				return a
			return combinerFunction(a, b)
		self.cmb = cmb
		self.sz = self.n if isCommutative else pow(2, (self.n - 1).bit_length())
		self.t = [None] * (2 * self.sz)
		for i in range(self.n):
			self.t[i + self.sz] = arr[i]
		for i in range(self.sz - 1, 0, -1):
			self.pull(i)

	def pull(self, p):
		self.t[p] = self.cmb(self.t[2 * p], self.t[2 * p + 1])

	def update(self, idx, val):
		idx += self.sz
		self.t[idx] = val
		idx //= 2
		while idx > 0:
			self.pull(idx)
			idx //= 2

	def query(self, l, r):
		l += self.sz
		r += self.sz + 1
		a = b = None
		while l < r:
			if l % 2 == 1:
				a = self.cmb(a, self.t[l])
				l += 1
			if r % 2 == 1:
				r -= 1
				b = self.cmb(self.t[r], b)
			l //= 2
			r //= 2
		return self.cmb(a, b)

def add(length):
	return length * (length + 1) // 2

def combiner(a, b):
	(alv, arv, all, arl, ac, ab) = a
	(blv, brv, bll, brl, bc, bb) = b
	(clv, crv, cll, crl, cc, cb) = (alv, brv, all, brl, ac + bc, ab or bb)
	if ab and bb:
		if arv <= blv:
			cc += add(arl + bll)
		else:
			cc += add(arl) + add(bll)
	elif ab and (not bb):
		if arv <= blv:
			crl += arl
		else:
			cc += add(arl)
	elif not ab and bb:
		if arv <= blv:
			cll += bll
		else:
			cc += add(bll)
	elif arv <= blv:
		cll = crl = all + bll
	else:
		cb = True
	return (clv, crv, cll, crl, cc, cb)

