def euclid(a, b):
	if b == 0:
		return (a, 1, 0)
	q = a // b
	(g, u, v) = euclid(b, a - q * b)
	return (g, v, u - q * v)

def modInverse(a, m):
	(g, u, v) = euclid(a, m)
	assert g == 1
	return u % m

def dpow(x, p, one, mul):
	ret = one
	while p > 0:
		if p % 2 == 1:
			ret = mul(ret, x)
		p //= 2
		x = mul(x, x)
	return ret

def dLog(x, y, one, mul, inv, limit):
	step = 1
	while step * step < limit:
		step += 1
	d = dict()
	invx = inv(x)
	cur = mul(invx, y)
	for i in range(1, step + 1):
		if cur not in d:
			d[cur] = i
		cur = mul(cur, invx)
	ret = limit + 1
	cur = one
	xstep = dpow(x, step, one, mul)
	for i in range(step):
		if cur in d:
			ret = min(ret, step * i + d[cur])
		cur = mul(cur, xstep)
	return -1 if ret == limit + 1 else ret
