			(j, res) = (i, False)
			while i < len(src):
				(res, i) = parseText(src, i)
				if res:
					continue
				(res, i) = parseCDData(src, i)
				if res:
					continue
				(res, i) = parseTag(src, i)
				if res:
					continue
				break
			return (True, i)

		def parseCDData(src, i):
			s = src.find('<![CDATA[', i)
			if s != i:
				return (False, i)
			e = src.find(']]>', i)
			return (True, e + 3) if e != -1 else (False, i)

		def parseText(src, i):
			j = i
			while i < len(src) and src[i] != '<':
				i += 1
			return (j != i, i)

