    max_distance = 0

    for i in range(0, len(x)):
        for j in range(i + 1, len(x)):
            # Find the current distance between two elements
            d = abs(x[i] - x[j])
            # Update the maximum distance 
            if max_distance < d: 
                max_distance = d

    return max_distance

