class DSU:

	def __init__(self, n):
		self.par = [i for i in range(n)]
		self.rank = [0] * n

	def find(self, node):
		if self.par[node] == node:
			return node
		self.par[node] = self.find(self.par[node])
		return self.par[node]

	def union(self, u, v):
		(u_p, v_p) = (self.find(u), self.find(v))
		if u_p == v_p:
			return
		if self.rank[u_p] > self.rank[v_p]:
			self.par[v_p] = u_p
		elif self.rank[u_p] < self.rank[v_p]:
			self.par[u_p] = v_p
		else:
			self.par[u_p] = v_p
			self.rank[u_p] += 1

class Solution:

	def MaxConnection(self, grid: List[List[int]]) -> int:
		n = len(grid)
		dsu = DSU(n * n)
		vis = set()
		dire = [(-1, 0), (0, 1), (1, 0), (0, -1)]

		def first_dfs(par_r, par_c, r, c):
			if r < 0 or c < 0 or r >= n or (c >= n) or ((r, c) in vis) or (grid[r][c] != 1):
				return
			vis.add((r, c))
			dsu.union(par_r * n + par_c, r * n + c)
			for i in dire:
				(x, y) = (r + i[0], c + i[1])
				first_dfs(par_r, par_c, x, y)
		for i in range(n):
			for j in range(n):
				if grid[i][j] == 1 and (i, j) not in vis:
					first_dfs(i, j, i, j)
		d = defaultdict(int)
		for i in dsu.par:
			d[dsu.find(i)] += 1
		maxi = 0
		for i in range(n):
			for j in range(n):
				if (i, j) not in vis and grid[i][j] == 0:
					new = set()
					ans = 1
					for k in dire:
						(x, y) = (i + k[0], j + k[1])
						if x >= 0 and y >= 0 and (x < n) and (y < n) and (grid[x][y] == 1):
							val = dsu.find(x * n + y)
							if val in new:
								continue
							new.add(val)
							ans += d[val]
					maxi = max(ans, maxi)
		if maxi:
			return maxi
		return n * n

