		result.append(A[window_negatives[0]])
	else:
		result.append(0)
	for i in range(K, N):
		while window_negatives and window_negatives[0] <= i - K:
			window_negatives.popleft()
		if A[i] < 0:
			window_negatives.append(i)
		if window_negatives:
			result.append(A[window_negatives[0]])
		else:
			result.append(0)
	return result

