class Solution:

	def findNumberOfGoodComponent(self, V, adj):
		visited = [0 for i in range(V + 1)]
		ans = 0
		for i in range(1, V + 1):
			count = [0]
			su = [0]
			if visited[i] == 0:
				self.dfs(i, visited, adj, count, su)
				if su[0] // 2 == count[0] * (count[0] - 1) // 2 or su[0] == 0:
					ans += 1
		return ans

	def dfs(self, node, visited, adj, count, su):
		visited[node] = 1
		for neigh in adj[node]:
			if visited[neigh] == 0:
				self.dfs(neigh, visited, adj, count, su)
		su[0] += len(adj[node])
		count[0] += 1

