class QuadTree:

	def __init__(self, pts):
		self.num = len(pts)
		yvals = sorted((pt[1] for pt in pts))
		self.box = (pts[0][0], yvals[0], pts[-1][0], yvals[-1])
		self.subtrees = []
		self.pts = []
		if self.box[0] < self.box[2] or self.box[1] < self.box[3]:
			i = (len(pts) - 1) // 2
			x = pts[i][0]
			y = yvals[i]
			parts = [[], [], [], []]
			for pt in pts:
				i = 1 if pt[0] > x else 0
				if pt[1] > y:
					i += 2
				parts[i].append(pt)
			for subpts in parts:
				if len(subpts) > 8:
					self.subtrees.append(QuadTree(subpts))
				else:
					self.pts.extend(subpts)

	def count(self, boxes):
		for box in boxes:
			if self.box[0] >= box[0] and self.box[1] >= box[1] and (self.box[2] <= box[2]) and (self.box[3] <= box[3]):
				return self.num
		keep = []
		for box in boxes:
			if self.box[0] <= box[2] and self.box[1] <= box[3] and (self.box[2] >= box[0]) and (self.box[3] >= box[1]):
				keep.append(box)
		n = 0
		if keep:
			for (x, y) in self.pts:
				for box in keep:
					if x >= box[0] and y >= box[1] and (x <= box[2]) and (y <= box[3]):
						n += 1
						break
			for subtree in self.subtrees:
				n += subtree.count(keep)
		return n

def toBoxes(pts):
	edges = []
	q = pts[-1]
	for p in pts:
		if p[1] == q[1]:
			if p[0] < q[0]:
				edges.append((p[0], q[0], p[1]))
			else:
				edges.append((q[0], p[0], p[1]))
		q = p
	edges.sort()
	i = 0
	boxes = []
	active = []
	left = edges[i][0]
	while i < len(edges) and edges[i][0] <= left:
		active.append(edges[i])
		i += 1
	while active:
		right = min((edge[1] for edge in active))
		if i < len(edges) and edges[i][0] < right:
			right = edges[i][0]
		active.sort(key=lambda edge: edge[2])
		for j in range(0, len(active), 2):
			boxes.append((left, active[j][2], right, active[j + 1][2]))
		active = [edge for edge in active if edge[1] > right]
		while i < len(edges) and edges[i][0] <= right:
			active.append(edges[i])
			i += 1
		left = right
	return boxes

