		for v in S:
			if ord('a') <= ord(v) and ord(v) <= ord('z'):
				s += chr(ord('z') - (ord(v) - ord('a')))
			elif ord('A') <= ord(v) and ord(v) <= ord('Z'):
				s += chr(ord('Z') - (ord(v) - ord('A')))
			else:
				s += v
		return s

class Solution:

	def countMin(self, s):
		n = len(s)
		rs = s[::-1]
		dp = [[0 for j in range(n + 1)] for i in range(n + 1)]
		for i in range(1, n + 1):
			for j in range(1, n + 1):
				if s[i - 1] == rs[j - 1]:
					dp[i][j] = 1 + dp[i - 1][j - 1]
				else:
					dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
		return n - dp[n][n]

