import bisect

class Solution:
    def minAbsDifference(self, nums: List[int], goal: int) -> int:
        pos = neg = 0
        for el in nums:
            if el >= 0:
                pos += el
            else:
                neg += el
        if goal >= pos:
            return goal - pos
        if goal <= neg:
            return neg - goal
        n = len(nums)
        k = n // 2
        x = [1] * max(k + 1, n - k + 1)
        for i in range(1, max(k + 1, n - k + 1)):
            x[i] = 2 * x[i - 1]
        sums = set()
        for mask in range(1 << k):
            s = 0
            for i in range(k):
                if mask & x[i]:
                    s += nums[i]
            sums.add(s)
        res = float('inf')
        sums = sorted(sums)
        for mask in range(1 << (n - k)):
            s = 0
            for i in range(n - k):
                if mask & x[i]:
                    s += nums[k + i]
            i = bisect.bisect_left(sums, goal - s)
            if i < len(sums):
                res = min(res, abs(s + sums[i] - goal))
            if i > 0:
                res = min(res, abs(s + sums[i - 1] - goal))
        return res

"""
Algorithm to determine the most common words in a given string
"""

def most_common_words(string):
    # split the string on whitespace
    words = string.split()

    # create a dictionary to store the count of each word 
    word_count = {}

    # for each word, add it to the dictionary or increment the count 
    for word in words:
        if word not in word_count:
            word_count[word] = 1
        else:
            word_count[word] += 1

    # convert the dictionary into a list of tuples (word, count)
    count_list = sorted(word_count.items(), key=lambda x: x[1], reverse=True)

    return count_list[0][0]

