class Solution:

	def util(self, root):
		global count
		if root == None:
			return [1, None]
		if root.left == None and root.right == None:
			count += 1
			return [1, root.data]
		l = self.util(root.left)
		r = self.util(root.right)
		if l[0] == 1 and r[0] == 1:
			if l[1] == None and r[1] == None:
				return [1, root.data]
			elif l[1] == None and r[1] == root.data:
				count += 1
				return [1, root.data]
			elif r[1] == None and l[1] == root.data:
				count += 1
				return [1, root.data]
			elif l[1] == r[1] and l[1] == root.data:
				count += 1
				return [1, root.data]
			else:
				return [0, root.data]
		else:
			return [0, root.data]

	def singlevalued(self, root):
		global count
		count = 0
		self.util(root)
		return count

