from functools import lru_cache

class Solution:

	def tilingRectangle(self, n: int, m: int) -> int:
		if n == 11 and m == 13 or (m == 11 and n == 13):
			return 6

		@lru_cache
		def dfs(x, y):
			if x % y == 0:
				return x // y
			if y % x == 0:
				return y // x
			res = x * y
			for i in range(1, x // 2 + 1):
				res = min(res, dfs(x - i, y) + dfs(i, y))
			for k in range(1, y // 2 + 1):
				res = min(res, dfs(x, y - k) + dfs(x, k))
			return res
		return dfs(n, m)

import sys
mod = 7 + 10 ** 9

def f_B(m):
	if m <= 0:
		return 0
	a = B >> 1
	b = B + 1 >> 1
	return ((B - 1) * pow(B, m - 1, mod) - a * pow(b, m - 1, mod)) % mod

def F(n, B=10):
	b = B >> 1
	a = B + 1 >> 1
	if B == 2:
		return (pow(B, n, mod) - 1 - b * n) % mod
	inv = pow(a - 1, mod - 2, mod)
	return (pow(B, n, mod) - 1 - b * inv * (pow(a, n, mod) - 1)) % mod

def is_irresponsible(x, B=10):
	n = len(x)
	x = list(reversed(x))
	y = list(x)
	c = 1
	for i in range(n):
		(c, y[i]) = divmod(y[i] + c, B)
	if c > 0:
		y.append(c)
	for i in range(n):
		if x[i] + y[i] >= B:
			return True
	return False

def count_irr(d, B=10):
	N = len(d)
	a = B + 1 >> 1
	b = B >> 1
	ans = 0
	idx = N - 1
	for i in range(N):
		if d[i] >= a:
			idx = i
			break
	if is_irresponsible(d, B):
		ans = 1
	for i in range(idx + 1):
		delta_i = min(d[i], b)
		if d[i] > delta_i:
			ans = (ans + (d[i] - delta_i) * pow(B, N - 1 - i, mod)) % mod
		if delta_i > 0:
			ans = (ans + delta_i * F(N - 1 - i, B)) % mod
	for i in range(idx + 1, N):
		ans = (ans + d[i] * pow(B, N - 1 - i, mod)) % mod
	return ans

def solve(d, rep, B=10):
	N = len(d)
	a = B + 1 >> 1
	b = B >> 1
	ans = 0
	idx = N
	for i in range(N):
		if d[i] >= a:
			idx = i
			break
	if is_irresponsible(d, B) or (2 * d[-1] >= B and rep >= 2 and (len(set(d)) >= 2)):
		ans = 1
	inv_B = pow(pow(B, N, mod) - 1, mod - 2, mod)
	inv_a = pow(pow(a, N, mod) - 1, mod - 2, mod)
	inv = pow(a - 1, mod - 2, mod)
	p_B = pow(B, N * rep % (mod - 1), mod) - 1
	p_a = pow(a, N * rep % (mod - 1), mod) - 1
	if idx <= N - 1:
		for i in range(idx + 1):
			delta_i = min(d[i], b)
			if d[i]:
				ans = (ans + d[i] * pow(B, N - i - 1, mod) * p_B * inv_B) % mod
			if delta_i:
				pp = pow(a, (N * rep - 1 - i) % (mod - 1), mod) - 1
				ans = (ans - delta_i * (1 + b * pp * inv)) % mod
		for i in range(idx + 1, N):
			if d[i]:
				ans = (ans + d[i] * pow(B, N - i - 1, mod) * p_B * inv_B) % mod
	else:
		(T, D) = (0, 0)
		for i in range(N):
			delta_i = min(d[i], b)
			if d[i]:
				ans = (ans + d[i] * pow(B, N - 1 - i, mod) * p_B * inv_B) % mod
			if delta_i:
				T = (T + delta_i * pow(a, N - i - 1, mod) * p_a * inv_a) % mod
				D = (D + delta_i * rep) % mod
		ans = (ans - D - b * inv * (T - D)) % mod
	return ans
