class Solution:

	def minScoreTriangulation(self, A: List[int]) -> int:
		N = len(A)
		dp = [[0] * N for _ in range(N)]
		for i in range(N - 2, -1, -1):
			for j in range(i + 2, N):
				dp[i][j] = min((dp[i][k] + dp[k][j] + A[i] * A[j] * A[k] for k in range(i + 1, j)))
		return dp[0][-1]

from typing import List

def findPar(node, parent):
	if node == parent[node]:
		return node
	parent[node] = findPar(parent[node], parent)
	return parent[node]

def union(u, v, rank, parent):
	(ult_u, ult_v) = (findPar(u, parent), findPar(v, parent))
	if ult_u == ult_v:
		return True
	if rank[ult_u] < rank[ult_v]:
		parent[ult_u] = ult_v
	elif rank[ult_v] < rank[ult_u]:
		parent[ult_v] = ult_u
	else:
		parent[ult_v] = ult_u
		rank[ult_u] += 1
	return False

class Solution:

	def numOfIslands(self, rows: int, cols: int, operators: List[List[int]]) -> List[int]:
		(rank, parent) = ([0] * (rows * cols), [i for i in range(rows * cols)])
		vis = [[0 for _ in range(cols)] for _ in range(rows)]
		dirc = [[-1, 0], [1, 0], [0, 1], [0, -1]]
		res = []
		cnt = 0
		for pair in operators:
			cnt += 1
			(r, c) = pair
			if vis[r][c] == 1:
				cnt -= 1
				res.append(cnt)
				continue
			vis[r][c] = 1
			u = r * cols + c
			for i in dirc:
				(x, y) = (r + i[0], c + i[1])
				v = x * cols + y
				if x < 0 or y < 0 or x >= rows or (y >= cols):
					continue
				if vis[x][y] == 1:
					if union(u, v, rank, parent) == False:
						cnt -= 1
			res.append(cnt)
		return res

