class Solution:

	def maxPrefixes(self, a, L, R, N, Q):
		for i in range(N - 1):
			a[i + 1] += a[i]
		a.insert(0, 0)
		output = []
		for i in range(Q):
			output.append(max(a[L[i] + 1:R[i] + 2]) - a[L[i]])
		return output

