def convex_hull(ps):
	qs = []
	N = len(ps)
	for p in ps:
		while len(qs) > 1 and cross3(qs[-1], qs[-2], p) > 0:
			qs.pop()
		qs.append(p)
	t = len(qs)
	for i in range(N - 2, -1, -1):
		p = ps[i]
		while len(qs) > t and cross3(qs[-1], qs[-2], p) > 0:
			qs.pop()
		qs.append(p)
	return qs

