class Solution:

	def maximizeEulerRatio(self, N):
		r = 1
		i = 2
		while r * i <= N:
			if self.isPrime(i):
				r *= i
			i += 1
		return r

	def isPrime(self, n):
		i = 2
		while i * i <= n:
			if n % i == 0:
				return False
			i += 1
		return True

