class Solution:

	def getLevelDiff(self, root):
		if root == None:
			return 0
		q = []
		q.append(root)
		reverse = True
		s = 0
		while q != []:
			c = len(q)
			for i in range(c):
				val = q.pop(0)
				if reverse == True:
					s += val.data
				else:
					s -= val.data
				if val.left != None:
					q.append(val.left)
				if val.right != None:
					q.append(val.right)
			reverse = ~reverse
		return s

class Solution:

	def findgroups(self, arr, n):
		c = [0, 0, 0]
		res = 0
		for i in range(0, n):
			c[arr[i] % 3] += 1
		res += c[0] * (c[0] - 1) >> 1
		res += c[1] * c[2]
		res += c[0] * (c[0] - 1) * (c[0] - 2) / 6
		res += c[1] * (c[1] - 1) * (c[1] - 2) / 6
		res += c[2] * (c[2] - 1) * (c[2] - 2) / 6
		res += c[0] * c[1] * c[2]
		return res

	def noOfGroups(self, N, Arr):
