class Solution:

	def isSuperSimilar(self, n, m, mat, x):
		for i in range(n):
			for j in range(m):
				x %= m
				if i % 2 == 0:
					if mat[i][j] != mat[i][(j + x) % m]:
						return 0
				elif mat[i][j] != mat[i][(j + m - x) % m]:
					return 0
		return 1

def save_gotham(arr, n):
	stack = [arr[n - 1]]
	ns = [0]
	for i in range(n - 2, -1, -1):
		if arr[i] < stack[-1]:
			ns.append(stack[-1])
		else:
			while len(stack) > 0 and stack[-1] <= arr[i]:
				stack.pop()
			if len(stack) == 0:
				ns.append(0)
			else:
				ns.append(stack[-1])
		stack.append(arr[i])
	return sum(ns) % 1000000001

