import heapq

def calc_dist(G, start):
	dist = [-1] * len(G)
	active = [(0, start)]
	while active:
		(d, i) = heapq.heappop(active)
		if dist[i] >= 0:
			continue
		dist[i] = d
		for (j, e) in G[i]:
			if dist[j] < 0:
				heapq.heappush(active, (d + e, j))
	return dist
