def prod(M, N, p):
	return [[mod(add(mult(M[0][0], N[0][0]), mult(M[0][1], N[1][0])), p), mod(add(mult(M[0][0], N[0][1]), mult(M[0][1], N[1][1])), p)], [mod(add(mult(M[1][0], N[0][0]), mult(M[1][1], N[1][0])), p), mod(add(mult(M[1][0], N[0][1]), mult(M[1][1], N[1][1])), p)]]

def puiss(M, n, r):
	L = [M]
	i = 1
	while i < n:
		L += [prod(L[-1], L[-1], r)]
		i *= 2
	e = 0
	N = [[(int(i == j), 0) for j in range(len(M))] for i in range(len(M))]
	while n:
		if n % 2:
			N = prod(N, L[e], r)
		n //= 2
		e += 1
	return N

