def solve(st):
	(res, s, k) = ([], '', 1)
	for ch in st:
		if ch == '(':
			res.append(k)
			k = 1
		elif ch == ')':
			res.pop()
			k = 1
		elif ch == '-':
			k = -1
		elif ch == '+':
			k = 1
