class Solution:

	def FindCoverage(self, matrix):
		coverageTotal = 0
		for i in range(len(matrix)):
			for j in range(len(matrix[0])):
				if matrix[i][j] == 0:
					if j - 1 >= 0 and matrix[i][j - 1] == 1:
						coverageTotal += 1
					if j + 1 < len(matrix[0]) and matrix[i][j + 1] == 1:
						coverageTotal += 1
					if i - 1 >= 0 and matrix[i - 1][j] == 1:
						coverageTotal += 1
					if i + 1 < len(matrix) and matrix[i + 1][j] == 1:
						coverageTotal += 1
		return coverageTotal

class Solution:

	def LargestSwap(self, S):
		n = len(S)
		arr = list(S)
		right = [0] * n
		right[n - 1] = n - 1
		rmax = n - 1
		for i in range(n - 2, -1, -1):
			right[i] = rmax
			if arr[i] > arr[rmax]:
				rmax = i
		for i in range(0, n):
			if arr[right[i]] > arr[i]:
				(arr[right[i]], arr[i]) = (arr[i], arr[right[i]])
				break
		return ''.join(arr)

class Solution:

	def expandIsland(self, grid, i, j):
		edges = [(i, j)]
		while edges:
			next_edges = []
			for edge in edges:
				(ei, ej) = edge
				if ei >= 0 and ei < len(grid) and (ej >= 0) and (ej < len(grid[ei])) and (grid[ei][ej] == '1'):
					grid[ei][ej] = '2'
					next_edges.append((ei + 1, ej))
					next_edges.append((ei, ej + 1))
					next_edges.append((ei - 1, ej))
					next_edges.append((ei, ej - 1))
			edges = next_edges

	def numIslands(self, grid):
		island_count = 0
		for i in range(len(grid)):
			for j in range(len(grid[i])):
				if grid[i][j] == '1':
					island_count += 1
					self.expandIsland(grid, i, j)
		return island_count

