def is_palindrome(num):
    temp = num
    rev = 0

    while (temp > 0):
        dig = temp % 10
        rev = rev * 10 + dig
        temp = temp // 10

    if (num == rev):
        return True
    else:
        return False

def getNthFromLast(head, n):
	count = 0
	temp = head
	while temp:
		count += 1
		temp = temp.next
	k = count - n
	if k < 0:
		return -1
	for x in range(0, k):
		head = head.next
	return head.data

