from collections import Counter

class Solution:
    def totalFruit(self, fruits: List[int]) -> int:
        n = len(fruits)
        i = 0
        ctr = Counter()
        mlen = 0
        for j in range(n):
            ctr[fruits[j]] += 1
            if len(ctr) <= 2:
                mlen = max(mlen, j - i + 1)
            else:
                while i < j and len(ctr) > 2:
                    ctr[fruits[i]] -= 1
                    if ctr[fruits[i]] == 0:
                        del ctr[fruits[i]]
                    i += 1
                if len(ctr) <= 2:
                    mlen = max(mlen, j - i + 1)
        return mlen

from functools import lru_cache

class Solution:

	def palindromePartition(self, s: str, k: int) -> int:
		n = len(s)
		if n == k:
			return 0

		@lru_cache(None)
		def cnt(left, right):
			if left >= right:
				return 0
			return cnt(left + 1, right - 1) + (s[left] != s[right])

		@lru_cache(None)
		def dp(length, partition):
			if partition == length:
				return 0
			if partition == 1:
				return cnt(0, length - 1)
			return min((dp(prelength, partition - 1) + cnt(prelength, length - 1) for prelength in range(partition - 1, length)))
		return dp(n, k)

class Solution:

	def countSubarray(self, arr, n, k):
		temp = 0
		ind = -1
		tot = 0
		for i in range(n):
			if arr[i] > k:
				temp = temp + i - ind
				ind = i
			tot = tot + temp
		return tot

class Solution:

	def searchMatrix(self, matrix, target):
		if not matrix or target is None:
			return False
		(rows, cols) = (len(matrix), len(matrix[0]))
		(low, high) = (0, rows * cols - 1)
		while low <= high:
			mid = (low + high) // 2
			num = matrix[mid // cols][mid % cols]
			if num == target:
				return True
			elif num < target:
				low = mid + 1
			else:
				high = mid - 1
		return False

