import bisect

class Solution:
    def smallerNumbersThanCurrent(self, nums: List[int]) -> List[int]:
        n = len(nums)
        ans = [0] * n
        order = sorted([(num, i) for i, num in enumerate(nums)])
        for i in range(n):
            pos = bisect.bisect_left(order, (order[i][0], float('-inf')))
            ans[order[i][1]] = i - max(i - pos, 0)
        return ans

from itertools import groupby

def replace(s):
	(queue, rle) = ({}, [[i, k, len(list(g))] for (i, (k, g)) in enumerate(groupby(s))])
	for (i, k, l) in reversed(rle):
		if l not in queue:
			queue[l] = {}
		queue[l].setdefault(k, []).append(i)
	for l in queue:
		while sum(map(bool, queue[l].values())) > 1:
			for c in queue[l]:
				rle[queue[l][c].pop()][1] = ' '
	return ''.join((k * l for (i, k, l) in rle))

