def tickets(people):
	till = {100.0: 0, 50.0: 0, 25.0: 0}
	for paid in people:
		till[paid] += 1
		change = paid - 25.0
		for bill in (50, 25):
			while bill <= change and till[bill] > 0:
				till[bill] -= 1
				change -= bill
		if change != 0:
			return 'NO'
	return 'YES'

class Solution:

	def superEggDrop(self, K: int, N: int) -> int:

		def f(t):
			a = 0
			r = 1
			for i in range(1, K + 1):
				r *= t - i + 1
				r //= i
				a += r
				if a >= N:
					break
			return a
		(l, h) = (1, N)
		while l < h:
			m = (l + h) // 2
			if f(m) < N:
				l = m + 1
			else:
				h = m
		return l

