class Edge:

	def __init__(self, to, rev, f, cap):
		self.to = to
		self.rev = rev
		self.f = f
		self.cap = cap

class DinicsAlgo:

	def __init__(self, N):
		self.dist = [-1] * N
		self.q = [0] * N
		self.g = [[] for i in range(N)]

	def add_edge(self, s, t, cap):
		a = Edge(s, len(self.g[s]), 0, cap)
		b = Edge(t, len(self.g[t]), 0, cap)
		self.g[s].append(b)
		self.g[t].append(a)

	def bfs(self, N):
		self.dist = [-1] * N
		self.dist[0] = 0
		qsz = 0
		self.q[qsz] = self.src
		qsz += 1
		i = 0
		while i < qsz:
			u = self.q[i]
			i += 1
			for e in self.g[u]:
				v = e.to
				if self.dist[v] < 0 and e.f < e.cap:
					self.dist[v] = self.dist[u] + 1
					self.q[qsz] = v
					qsz += 1
		return self.dist[self.dest] >= 0

	def dfs(self, u, f):
		if u == self.dest:
			return f
		for e in self.g[u]:
			if e.cap <= e.f:
				continue
			v = e.to
			if self.dist[v] == self.dist[u] + 1:
				df = self.dfs(v, min(f, e.cap - e.f))
				if df > 0:
					e.f += df
					self.g[v][e.rev].f -= df
					return df
		return 0

	def mf(self, s, t, N):
		self.src = s
		self.dest = t
		ret = 0
		while self.bfs(N):
			delta = self.dfs(s, 1000000000)
			while delta:
				ret += delta
				delta = self.dfs(s, 1000000000)
		return ret

def dfs_up(node, G):
	up[node] = 1
	for e in G.g[node]:
		if e.cap > e.f and up[e.to] == -1:
			dfs_up(e.to, G)
