class Solution:

	def lca(self, root, n1, n2):
		if root is None:
			return None
		if root.data == n1 or root.data == n2:
			return root
		in_left_tree = self.lca(root.left, n1, n2)
		in_right_tree = self.lca(root.right, n1, n2)
		if in_left_tree and in_right_tree:
			return root
		else:
			return in_left_tree or in_right_tree

