def count_ways(N, M, D):
	ways = [[[0] * D[i] for _ in range(M + 1)] for i in range(N)]
	for i in range(N):
		for j in range(D[i]):
			ways[i][0][j] = 1
			if j > 0:
				ways[i][1][j] += 1
			if j < D[i] - 1:
				ways[i][1][j] += 1
		for s in range(2, M + 1):
			for j in range(D[i]):
				if j > 0:
					ways[i][s][j] += ways[i][s - 1][j - 1]
				if j < D[i] - 1:
					ways[i][s][j] += ways[i][s - 1][j + 1]
	return ways
