def palin_perm(s: str) -> List[int]:
	n = len(s)
	counts = Counter(s)
	odds = 0
	for count in counts.values():
		if count & 1:
			odds += 1
	if n & 1 and odds > 1 or (not n & 1 and odds > 0):
		return [-1]
	inds = {i: [] for i in s}
	for i in range(n):
		inds[s[i]].append(i + 1)
	res = [-1] * n
	if n & 1:
		for (key, val) in counts.items():
			if val & 1:
				let = key
				poses = inds[key]
				del inds[key]
		i = 0
		for pos in inds.values():
			while pos:
				res[i] = pos.pop()
				res[n - i - 1] = pos.pop()
				i += 1
		for x in poses:
			res[i] = x
			i += 1
	else:
		i = 0
		for pos in inds.values():
			while pos:
				res[i] = pos.pop()
				res[n - i - 1] = pos.pop()
				i += 1
	return res
