	return (False, s_arr)

def dfs(u, d, used, cur):
	used[u] = True
	cur.append(u)
	flg = False
	for v in d[u]:
		if used[v] == True:
			return True
		flg = dfs(v, d, used, cur)
		if flg == True:
			return flg
	return flg

