class Solution:

	def NthRoot(self, n, m):
		low = 1
		high = m
		while low <= high:
			mid = (low + high) // 2
			if pow(mid, n) == m:
				return mid
			if pow(mid, n) < m:
				low = mid + 1
			else:
				high = mid - 1
