MODULO = 1000000007

def find_path(node, children, a, b, vis):
	connected = False
	vis[node] = True
	(ret_req, ret_avail, children_comb) = (None, None, 1)
	for child in children[node]:
		if vis[child]:
			continue
		(req, avail, comb) = find_path(child, children, a, b, vis)
		if req:
			if connected:
				return (None, None, None)
			connected = True
			if a[node] != b[node]:
				if b[node] in avail:
					if avail[b[node]] == 1:
						del avail[b[node]]
					else:
						avail[b[node]] -= 1
				elif b[node] in req:
					req[b[node]] += 1
				else:
					req[b[node]] = 1
				if a[node] in req:
					if req[a[node]] == 1:
						del req[a[node]]
					else:
						req[a[node]] -= 1
				elif a[node] in avail:
					avail[a[node]] += 1
				else:
					avail[a[node]] = 1
			(ret_req, ret_avail) = (req, avail)
		elif req is None:
			return (None, None, None)
		children_comb = children_comb * comb
	if not connected:
		(ret_req, ret_avail) = ({}, {})
		if a[node] != b[node]:
			ret_req[b[node]] = 1
			ret_avail[a[node]] = 1
		if node != 0:
			children_comb = children_comb * len(children[node])
		else:
			children_comb = children_comb * (len(children[node]) + 1)
	return (ret_req, ret_avail, children_comb)
