	for i in range(n):
		if vis[i]:
			continue
		ss = ''
		j = i
		ss += s[j]
		vis[j] = True
		j = p[j]
		while j != i:
			ss += s[j]
			vis[j] = True
			j = p[j]
		ln = shift(ss)
		ans = ans * ln // math.gcd(ans, ln)
