def doubling(n, m, mod):
	y = 1
	base = n
	while m != 0:
		if m % 2 == 1:
			y *= base
			y %= mod
		base *= base
		base %= mod
		m //= 2
	return y

def factorization(n):
	if n == 1:
		return {1: 1}
	else:
		D = {}
		base = n
		p = 2
		while n != 1:
			i = 0
			while n % p == 0:
				i += 1
				n //= p
			if i != 0:
				D[p] = i
			p += 1
			if p * p > base and n != 1:
				D[n] = 1
				break
		return D

