def Resque(a, mod):
	if mod == 1:
		return 1
	M = Torshent(mod)
	MM = gcd(M, mod)
	R = Resque(a, MM)
	k = doubling(a, R, mod)
	(m, modmod) = (M // MM, mod // MM)
	Tm = Torshent(modmod)
	invm = doubling(m, Tm - 1, modmod)
	t = (k - R) // MM * invm
	R += t * M
	R %= mod * M // MM
	R += mod * M // MM
	return R
