def build_tree(arr):
	n = len(arr)
	n1 = 2 ** math.ceil(math.log2(n))
	st = [0] * (2 * n1 - 1)

	def builder(segment_start, segment_end, st_idx):
		if segment_end == segment_start:
			st[st_idx] = segment_start
		else:
			mid = get_mid(segment_start, segment_end)
			b1 = builder(segment_start, mid, st_idx * 2 + 1)
			b2 = builder(mid + 1, segment_end, st_idx * 2 + 2)
			if arr[b1] <= arr[b2]:
				st[st_idx] = b1
			else:
				st[st_idx] = b2
		return st[st_idx]
	builder(0, n - 1, 0)
	return st

def query_tree(st, arr, query_start, query_end):
	len_arr = len(arr)

	def q(range_start, range_end, st_idx):
		if query_start <= range_start and range_end <= query_end:
			return st[st_idx]
		elif query_end < range_start or range_end < query_start:
			return -1
		else:
			mid = get_mid(range_start, range_end)
			b1 = q(range_start, mid, st_idx * 2 + 1)
			b2 = q(mid + 1, range_end, st_idx * 2 + 2)
			assert b1 > -1 or b2 > -1
			if b2 == -1:
				return b1
			elif b1 == -1:
				return b2
