		if f.state == 1:
			if f.parent >= 0:
				trail.append(f.parent)
			stack.pop()
			continue
		trail.append(f.node)
		levels_by_node[f.node] = f.level
		D[f.node] = f.d
		C[f.node] = f.c
		S[f.node] = f.s
		for (child, weight) in adj[f.node]:
			if child != f.parent:
				stack.append(F(child, f.node, f.level + 1, d=f.d + weight, c=f.c + (f.d + weight) * A[child], s=f.s + A[child]))
		f.state = 1
	return (trail, [levels_by_node[t] for t in trail], D, C, S)

def do_dfs(adj, root, A):
	N = max(adj)
	trail = []
	levels_by_node = [0] * (N + 1)
	D = [0] * (N + 1)
	C = [0] * (N + 1)
	S = [0] * (N + 1)

	def dfs(node, parent, level, d, c, s):
		trail.append(node)
		levels_by_node[node] = level
		D[node] = d
		C[node] = c
		S[node] = s
		for (child, weight) in adj[node]:
			if child != parent:
				dfs(child, node, level + 1, d=d + weight, c=c + (d + weight) * A[child], s=s + A[child])
				trail.append(node)
	dfs(root, -1, 0, d=0, c=0, s=A[root])
	return (trail, [levels_by_node[t] for t in trail], D, C, S)

def solve(A, edges, queries):
	adj = defaultdict(list, {})
	for (e1, e2, w) in edges:
		adj[e1].append((e2, w))
		adj[e2].append((e1, w))
	root = next((k for (k, c) in adj.items() if len(c) == 1))
	(trail, levels, D, C, S) = do_dfs2(adj, root, A)
	node_to_idx = {}
	for (idx, node) in enumerate(trail):
		if node not in node_to_idx:
			node_to_idx[node] = idx
	st = build_tree(levels)

	def lca(x, y):
		xi = node_to_idx[x]
		yi = node_to_idx[y]
		levels_idx = query_tree(st, levels, min(xi, yi), max(xi, yi))
		return trail[levels_idx]

	def a(x, y):
		p = lca(x, y)
		sum_a_p1 = S[x] - S[p] + A[p]
		sum_a_p2 = S[y] - S[p]
		coef1 = D[x] - D[y] + 2 * D[p]
		coef2 = D[x] - D[y] - 2 * D[p]
		sum_of_akdk_p1 = C[x] - C[p] + A[p] * D[p]
		sum_of_akdk_p2 = C[y] - C[p]
		return coef1 * sum_a_p1 + coef2 * sum_a_p2 - 2 * sum_of_akdk_p1 + 2 * sum_of_akdk_p2
	return [a(x, y) for (x, y) in queries]

