import queue

class Solution:

	def nodeLevel(self, v, adjList, x):
		vis = [-1] * v
		s = queue.Queue()
		src = 0
		count = 0
		s.put([count, src])
		while not s.empty():
			(count, node) = s.get()
			if node == x:
				return count
			for i in adjList[node]:
				if i == x:
					return count + 1
				if vis[i] == -1:
					s.put([count + 1, i])
					vis[i] = 1
		return -1

