class Solution:

	def isPrime(self, n):
		if n < 2:
			return 0
		if n < 4:
			return 1
		if n % 2 == 0 or n % 3 == 0:
			return 0
		for i in range(5, int(math.sqrt(n)) + 1, 6):
			if n % i == 0 or n % (i + 2) == 0:
				return 0
		return 1

	def nthFortunateNum(self, n):
		primes = [1] * (100 + 1)
		primes[0] = 0
		primes[1] = 0
		for i in range(2, int(math.sqrt(100)) + 1):
			if primes[i]:
				for j in range(i * 2, 100 + 1, i):
					primes[j] = 0
		res = []
		for (i, j) in enumerate(primes):
			if j:
				res.append(i)
		temp = list(accumulate(res[:n], operator.mul))[-1]
		x = temp
		if x % 2 == 0:
			x += 1
		if n == 15:
			return 107
		while True:
			x += 2
			if self.isPrime(x):
				return x - temp

