def next_token():
	global dig, k, limit
	if k == limit:
		k = 0
		dig += 1
		limit = 26 ** dig
	w = []
	l = k
	for _ in range(dig):
		w += chr(ord('a') + l % 26)
		l //= 26
	w = ''.join(reversed(w))
	k += 1
	if w in reserved:
		return next_token()
	return w
