def upn(inputs):
	res = 0
	stack = []
	for inp in inputs:
		if inp in ['+', '-', '*', '/']:
			b = stack.pop()
			a = stack.pop()
			c = str(eval(a + inp + b))
			stack.append(c)
		else:
			stack.append(inp)
	return float(stack[0])
