class Solution:

	def LargestProductPalin(self, n):
		upper_limit = 10 ** n - 1
		lower_limit = 1 + upper_limit // 10
		max_product = 0
		for i in range(upper_limit, lower_limit - 1, -1):
			for j in range(i, lower_limit - 1, -1):
				product = i * j
				if product < max_product:
					break
				number = product
				reverse = 0
				while number != 0:
					reverse = reverse * 10 + number % 10
					number = number // 10
				if product == reverse and product > max_product:
					max_product = product
		return max_product

class Solution:

	def canPair(self, nums, k):
		remainder_count = {}
		for num in nums:
			remainder = num % k
			if remainder in remainder_count:
				remainder_count[remainder] += 1
			else:
				remainder_count[remainder] = 1
		for num in nums:
			remainder = num % k
			complement = (k - remainder) % k
			if remainder == complement:
				if remainder_count[remainder] % 2 != 0:
					return False
			elif remainder_count.get(remainder, 0) != remainder_count.get(complement, 0):
				return False
		return True

