def query(l, r, x, y):
	ans = 0
	l += n
	r += n
	while l < r:
		if l & 1:
			forx = bisect_left(tree[l], x)
			fory = bisect(tree[l], y)
			ans += fory - forx
			l += 1
		if r & 1:
