def leftCandies(n, m):
	candy_left = m % (n * (n + 1) // 2)
	start = 0
	end = n
	while start <= end:
		mid = (start + end) // 2
		curr = mid * (mid + 1) // 2
		if curr == candy_left:
			return 0
		elif curr > candy_left:
			end = mid - 1
		else:
			start = mid + 1
	return candy_left - end * (end + 1) // 2

