			else:
				if face == 0:
					for i in range(1, command + 1):
						if (x, y + i) in obstacles:
							i -= 1
							break
					y += i
				elif face == 1:
					for i in range(1, command + 1):
						if (x + i, y) in obstacles:
							i -= 1
							break
					x += i
				elif face == 2:
					for i in range(1, command + 1):
						if (x, y - i) in obstacles:
							i -= 1
							break
					y -= i
				else:
					for i in range(1, command + 1):
						if (x - i, y) in obstacles:
							i -= 1
							break
					x -= i
				max_dist = max(max_dist, x ** 2 + y ** 2)
