class Solution:

	def longestConsecutive(self, nums):
		longest_streak = 0
		num_set = set(nums)
		for num in num_set:
			if num - 1 not in num_set:
				current_num = num
				current_streak = 1
				while current_num + 1 in num_set:
					current_num += 1
					current_streak += 1
				longest_streak = max(longest_streak, current_streak)
		return longest_streak

def findBetween(a1, a2, b):
	start_b = b
	while b is not None and a1.data <= b.data <= a2.data:
		if b.next is None or b.next.data > a2.data:
			break
		b = b.next
	return (start_b, b)

def sortedMerge(head1, head2):
	temp_node = Node(-1)
	temp_node.next = head1
	(a1, a2, b) = (temp_node, temp_node.next, head2)
	next_b = b
	while a2 is not None and next_b is not None:
		(start_b, b) = findBetween(a1, a2, next_b)
		if a1.data <= start_b.data <= a2.data:
			next_b = b.next
			a1.next = start_b
			b.next = a2
		a1 = a2
		if a2.next is None and next_b is not None:
			a2.next = next_b
