def spaces(a, n, m, k, visit1, visit2, dist, position):
	queue = [position]
	lastedit = []
	dist[position[0]][position[1]] = 0
	while queue != []:
		point = queue[0]
		i = point[0]
		j = point[1]
		if visit1[i][j] == False:
			visit1[i][j] = True
			startx = max(i - k, 0)
			endx = min(i + k, n - 1)
			for x in range(startx, endx + 1):
				starty = max(0, j + abs(x - i) - k)
				endy = min(m - 1, j - abs(x - i) + k)
				for y in range(starty, endy + 1):
