class Solution:
    def shoppingOffers(self, price: List[int], special: List[List[int]], needs: List[int]) -> int:
        dist = defaultdict(lambda: float('inf'))
        beg = tuple([0] * len(needs))
        dist[beg] = 0
        heap = [(0, beg)]
        while len(heap) > 0:
            cost, curr = heapq.heappop(heap)
            if list(curr) == needs:
                return cost
            for i in range(len(price)):
                if curr[i] + 1 <= needs[i]:
                    newcurr = list(curr)
                    newcurr[i] += 1
                    newcurr = tuple(newcurr)
                    if dist[newcurr] > cost + price[i]:
                        dist[newcurr] = cost + price[i]
                        heapq.heappush(heap, (dist[newcurr], newcurr))
            for offer in special:
                newcurr = list(curr)
                valid = True
                for i in range(len(curr)):
                    if newcurr[i] + offer[i] > needs[i]:
                        valid = False
                        break
                    newcurr[i] += offer[i]
                newcurr = tuple(newcurr)
                if valid and dist[newcurr] > cost + offer[-1]:
                    dist[newcurr] = cost + offer[-1]
                    heapq.heappush(heap, (dist[newcurr], newcurr))
        return -1

import numpy as np

def slope(p1, p2):
	(dx, dy) = vectorize(p1, p2)
	return dy / dx if dx else float('inf')

def vectorize(p1, p2):
	return [b - a for (a, b) in zip(p1, p2)]

def getArea(p1, p2, p3):
	return np.cross(vectorize(p1, p2), vectorize(p1, p3)) / 2

def isConcave(p1, pivot, p2):
	return getArea(pivot, p1, p2) >= 0

def convex_hull_area(points):
	if len(points) < 3:
		return 0
	Z = min(points)
	q = sorted((pt for pt in points if pt != Z), key=lambda pt: (-slope(pt, Z), -np.linalg.norm(vectorize(Z, pt))))
	hull = [Z, q.pop()]
	while q:
		pt = q.pop()
		while len(hull) > 1 and isConcave(hull[-2], hull[-1], pt):
			hull.pop()
		hull.append(pt)
	area = sum((getArea(Z, hull[i], hull[i + 1]) for i in range(1, len(hull) - 1)))
	return round(area, 2)

