class Solution:

	def lexicographicallyLargest(self, a, n):
		(i, j) = (0, 1)
		while i < n - 1 and j < n:
			if (a[i] + a[j]) % 2 == 0:
				j += 1
			else:
				a[i:j] = sorted(a[i:j], reverse=True)
				i = j
				j += 1
			if j == n:
				a[i:j] = sorted(a[i:j], reverse=True)
		return a

