def compute(A):
	ans = 0
	N = len(A)
	for i in range(N):
		k = i + 1
		for j in range(i + 2, N):
			mid = (A[i] + A[j]) / 2
			while k < j - 1 and abs(A[k + 1] - mid) <= abs(A[k] - mid):
				k += 1
			ans += (A[k] - A[i]) * (A[j] - A[k])
	return ans
