class Solution:

	def PredictTheWinner(self, nums):
		if not nums:
			return True
		n = len(nums)
		if n & 1 == 0:
			return True
		dp = [0] * n
		for i in range(n - 1, -1, -1):
			for j in range(i, n):
				if i == j:
					dp[i] = nums[i]
				else:
					dp[j] = max(nums[i] - dp[j], nums[j] - dp[j - 1])
		return dp[n - 1] >= 0

def subsets(s):
    res = []
    for i in range(1 << len(s)):
        subset = [list(s)[x] for x in range(len(s)) if i & (1 << x)]
        if not any(set(subset).issubset(r) for r in res):
            res.append(subset)
    return res

def solve():
	from math import sqrt
	from sys import stdin
	f_i = stdin

	def dfs(point, remain, elapsed):
		if not remain:
			return True
		next_c = set()
		for c in remain:
			new_elapsed = elapsed + adj[point][c]
			if new_elapsed >= from_d[c]:
				return False
			next_c.add((c, new_elapsed))
		for (c, new_elapsed) in next_c:
